import{_ as t,o as a,c as r,a0 as s}from"./chunks/framework.lnbZLl6b.js";const o="/projects/aquilifer/screenshots/history-entry.png",u=JSON.parse('{"title":"History","description":"","frontmatter":{},"headers":[],"relativePath":"docs/history.md","filePath":"docs/history.md"}'),i={name:"docs/history.md"};function n(l,e,d,h,c,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h1><p>Every request a connected site makes is logged: which site, when, what was asked, and what came back (or the error, if it failed). It&#39;s a read-only audit log for <em>you</em>, viewable from the <strong>History</strong> tab in settings.</p><p><img src="'+o+'" alt="A History entry card showing the site, timestamp, provider, prompt, and a markdown-rendered response with bold text and a bullet list"></p><h2 id="it-s-audit-only-never-replayed" tabindex="-1">It&#39;s audit-only, never replayed <a class="header-anchor" href="#it-s-audit-only-never-replayed" aria-label="Permalink to &quot;It&#39;s audit-only, never replayed&quot;">​</a></h2><p>Aquilifer never feeds history back into a future request. Every call is stateless: a site sends the full conversation it wants answered on that one call, exactly like calling the underlying provider&#39;s API directly. This is deliberate: it avoids silent, creeping token costs from an ever-growing conversation you didn&#39;t ask to keep paying for, and it means history is purely something you can look back at, not something that quietly affects behavior.</p><h2 id="kept-separately-per-interface" tabindex="-1">Kept separately per interface <a class="header-anchor" href="#kept-separately-per-interface" aria-label="Permalink to &quot;Kept separately per interface&quot;">​</a></h2><p>Aquilifer&#39;s generic chat interface and each provider-specific interface keep their own history log, viewable from separate tabs, so if you only ever use one, its log doesn&#39;t get lost in a mix of everything.</p><p>The generic chat tab renders prompts and responses as real markdown (headings, code blocks, lists, and the like) instead of showing the raw <code>##</code>/<code>```</code> syntax as plain text. The provider-specific tabs (Anthropic Messages, OpenAI Chat Completions) show a compact JSON summary of the request/response instead, so those stay plain text.</p><h2 id="dark-or-light-entry-cards" tabindex="-1">Dark or light entry cards <a class="header-anchor" href="#dark-or-light-entry-cards" aria-label="Permalink to &quot;Dark or light entry cards&quot;">​</a></h2><p>History entries render on their own card, separate from the page&#39;s base background. A <strong>Dark</strong>/<strong>Light</strong> toggle next to the History heading switches which. Dark (the default) follows the same colors as the rest of the extension; Light uses a parchment-style card instead. Your choice is remembered.</p><h2 id="what-it-doesn-t-do" tabindex="-1">What it doesn&#39;t do <a class="header-anchor" href="#what-it-doesn-t-do" aria-label="Permalink to &quot;What it doesn&#39;t do&quot;">​</a></h2><ul><li>History is <strong>not sent anywhere</strong>; it&#39;s stored locally in the browser, like everything else Aquilifer keeps.</li><li>It&#39;s <strong>not encrypted</strong>, even if you&#39;ve turned on <a href="/projects/aquilifer/docs/vault">the vault</a>: the vault only protects API keys. If you&#39;re typing anything sensitive into a site that uses Aquilifer, know that a record of it sits in local, unencrypted browser storage. See <a href="/projects/aquilifer/docs/limitations">Limitations</a> for more on this.</li><li>A connected site can read its <em>own</em> history back (so it can show a user their own past requests, for example), never another site&#39;s.</li></ul>',12)])])}const f=t(i,[["render",n]]);export{u as __pageData,f as default};
